questionvariables.text:
/* Forest fertiliser: trees nested within eight plots */
plot_n0:[10,15,30,45,45,30,15,10];
shift:rand(4);
f_pattern:[12,14,17,21];
f_means0:makelist(f_pattern[k]+shift+rand(3)-1,k,1,4);
c_pattern:[10,12,15,17];
c_means0:makelist(c_pattern[k]+shift+rand(3)-1,k,1,4);
plot_means0:append(f_means0,c_means0);

/* Randomise plot labels, preserving each plot's size and mean. */
plot_order:random_permutation(makelist(k,k,1,8));
plot_n:makelist(plot_n0[plot_order[k]],k,1,8);
plot_means:makelist(plot_means0[plot_order[k]],k,1,8);
is_fert:makelist(if plot_order[k]<=4 then 1 else 0,k,1,8);
treatments:makelist(if is_fert[k]=1 then "Fertiliser" else "Control",k,1,8);

/* Generate individual measurements in balanced +/- pairs.
   Each plot's actual mean is exactly plot_means[k]. */
tree_rows(i):=block([ni,half,offs,vals,j],
  ni:plot_n[i],
  half:floor(ni/2),
  offs:makelist(rand(5)-2,j,1,half),
  vals:append(
    makelist(plot_means[i]+offs[j],j,1,half),
    makelist(plot_means[i]-offs[j],j,1,half)
  ),
  if mod(ni,2)=1 then vals:append(vals,[plot_means[i]]),
  vals:random_permutation(vals),
  makelist([sconcat("P",i),sconcat("T",j),treatments[i],vals[j]],j,1,ni)
);
tree_data:apply(append,makelist(tree_rows(i),i,1,8));
tree_data:random_permutation(tree_data);
lab:["Plot_ID","Tree_ID","Treatment","Growth_cm"];

/* Equal-weight means: each experimental plot counts once. */
mean_f:sum(is_fert[k]*plot_means[k],k,1,8)/4;
mean_c:sum((1-is_fert[k])*plot_means[k],k,1,8)/4;
ta_diff:float(mean_f-mean_c);

/* Plausible but different answer: average all measured trees. */
nf:sum(is_fert[k]*plot_n[k],k,1,8);
nc:sum((1-is_fert[k])*plot_n[k],k,1,8);
tree_mean_f:sum(is_fert[k]*plot_n[k]*plot_means[k],k,1,8)/nf;
tree_mean_c:sum((1-is_fert[k])*plot_n[k]*plot_means[k],k,1,8)/nc;
ta_tree_diff:float(tree_mean_f-tree_mean_c);

/* Diagnostic answers for targeted feedback. */
ta_control_plots:sum(1-is_fert[k],k,1,8);
ta_control_tree_rows:nc;
/* Tree_ID restarts at T1 in every plot; the largest control plot
   determines the number of distinct Tree_ID labels. */
ta_distinct_control_tree_ids:apply(max,makelist(if is_fert[k]=0 then plot_n[k] else 0,k,1,8));
ta_all_plot_mean:sum(plot_means[k],k,1,8)/8;
ta_reversed_diff:mean_c-mean_f;
ta_wrong_fert_minus_all:mean_f-ta_all_plot_mean;
ta_wrong_all_minus_control:ta_all_plot_mean-mean_c;

/* Input model answers */
ta_plots:8;
ta_level:[[1,false,"Individual tree"],
          [2,true,"Forest plot"],
          [3,false,"Entire forest"]];
